H.background();
const n = Math.max(1, Math.round(P.n));
const xv = P.x, yv = P.y;
const w = H.W, hgt = H.H;
function fact(k){ let r = 1; for (let i = 2; i <= k; i++) r *= i; return r; }
function comb(nn, kk){ return fact(nn) / (fact(kk) * fact(nn - kk)); }
H.text("Binomial theorem: (x + y)^n = sum C(n,k) x^(n-k) y^k", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("n = " + n + "    x = " + xv.toFixed(1) + "    y = " + yv.toFixed(1), 24, 52, { color: H.colors.sub, size: 13 });
// Sweep which term is highlighted with t (loops through the n+1 terms).
const active = Math.floor(t * 0.8) % (n + 1);
const x0 = 60, baseY = hgt - 70;
const colW = Math.min(120, (w - 120) / (n + 1));
let total = 0, partial = 0;
for (let k = 0; k <= n; k++){
  const c = comb(n, k);
  const term = c * Math.pow(xv, n - k) * Math.pow(yv, k);
  total += term;
}
for (let k = 0; k <= n; k++){
  const c = comb(n, k);
  const term = c * Math.pow(xv, n - k) * Math.pow(yv, k);
  const frac = total !== 0 ? Math.abs(term) / Math.abs(total) : 0;
  const barH = 20 + 140 * Math.min(1, frac);
  const cx = x0 + k * colW;
  const on = k === active;
  if (k <= active) partial += term;
  H.rect(cx, baseY - barH, colW - 12, barH, { fill: on ? H.colors.accent : H.colors.panel, stroke: H.colors.grid, width: 1.5, radius: 4 });
  H.text("C(" + n + "," + k + ")=" + c, cx, baseY - barH - 18, { color: on ? H.colors.ink : H.colors.sub, size: 12, weight: on ? 700 : 500 });
  H.text("x^" + (n - k) + " y^" + k, cx, baseY + 18, { color: H.colors.sub, size: 11 });
  H.text(term.toFixed(1), cx, baseY - barH + 14, { color: H.colors.ink, size: 11 });
}
H.line(x0 - 6, baseY, x0 + (n + 1) * colW, baseY, { color: H.colors.axis, width: 1.5 });
H.text("running sum of terms 0.." + active + " = " + partial.toFixed(2) + "   (full = " + total.toFixed(2) + ")", 24, hgt - 24, { color: H.colors.good, size: 13 });
